import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"GLM Coding Plan 学习地图","description":"GLM Coding Plan 是智谱给指定编程工具用的订阅套餐，不是清言，也不是再做一个聊天产品。本目录只写套餐边界和怎么接到 Claude Code / Cursor 等。","frontmatter":{"title":"GLM Coding Plan 学习地图","description":"GLM Coding Plan 是智谱给指定编程工具用的订阅套餐，不是清言，也不是再做一个聊天产品。本目录只写套餐边界和怎么接到 Claude Code / Cursor 等。","domain":"product","tags":["coding-plan"],"role":"map"},"headers":[],"relativePath":"zh/products/glm-coding/index.md","filePath":"zh/products/glm-coding/index.md","lastUpdated":1787110548000}'),d={name:"zh/products/glm-coding/index.md"};function o(l,t,s,i,c,p){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="glm-coding-plan-学习地图" tabindex="-1">GLM Coding Plan 学习地图 <a class="header-anchor" href="#glm-coding-plan-学习地图" aria-label="Permalink to &quot;GLM Coding Plan 学习地图&quot;">​</a></h1><blockquote><p><strong>GLM Coding Plan</strong> 是专为 AI 编码打造的<strong>订阅套餐</strong>。它把额度卖给你，让你在官方指定的 Claude Code、Cursor 等工具里调用 GLM。它<strong>不是</strong>聊天窗口，也<strong>不是</strong>智谱自己的终端 Agent。</p><p>官方定义（<a href="https://docs.bigmodel.cn/cn/coding-plan/overview" target="_blank" rel="noreferrer">套餐概览</a>）： 「GLM Coding Plan 是专为 AI 编码打造的订阅套餐，仅需少量投入，即可覆盖需求理解、代码生成、调试修复、代码库问答与自动化任务处理等开发全流程。」</p></blockquote><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>智谱同时卖聊天、开放平台 API、以及这套「给现有编程助手加油」的订阅。本目录的<strong>主学习路径</strong>只有 <strong>GLM Coding Plan</strong>。清言 / Z.ai 正文见 <a href="https://github.com/zenHeart/learn-ai/issues/74" target="_blank" rel="noreferrer">#74</a>，这里只占一行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>智谱 / Zhipu</span></span>
<span class="line"><span>├── 智谱清言 — chatglm.cn（聊天 / Agent，#74）</span></span>
<span class="line"><span>├── Z.ai — z.ai（海外聊天 / Agent，#74）</span></span>
<span class="line"><span>├── BigModel 开放平台 — bigmodel.cn（标准按量 API）</span></span>
<span class="line"><span>├── GLM Coding Plan — 指定工具里的编码订阅（本目录）</span></span>
<span class="line"><span>│   ├── 个人：Lite / Pro / Max</span></span>
<span class="line"><span>│   ├── 团队：标准版 / 高级版</span></span>
<span class="line"><span>│   └── 装载：npx @z_ai/coding-helper（只覆盖部分 CLI）</span></span>
<span class="line"><span>└── 其它一级产品 — AutoGLM / AutoClaw / ZCode / Zread.ai …</span></span></code></pre></div><table tabindex="0"><thead><tr><th>官方一级入口</th><th>是什么</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>GLM Coding Plan</strong></td><td>指定编程工具里的订阅额度</td><td><a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">bigmodel.cn/glm-coding</a>、<a href="https://docs.bigmodel.cn/cn/coding-plan/overview" target="_blank" rel="noreferrer">套餐概览</a></td><td>本目录独立页</td></tr><tr><td>智谱清言</td><td>面向消费者的聊天 / Agent</td><td><a href="https://chatglm.cn/" target="_blank" rel="noreferrer">chatglm.cn</a></td><td>地图一行，正文 <a href="https://github.com/zenHeart/learn-ai/issues/74" target="_blank" rel="noreferrer">#74</a></td></tr><tr><td>Z.ai</td><td>海外聊天 / Agent 与 API 入口</td><td><a href="https://z.ai/" target="_blank" rel="noreferrer">z.ai</a></td><td>地图一行，正文 <a href="https://github.com/zenHeart/learn-ai/issues/74" target="_blank" rel="noreferrer">#74</a></td></tr><tr><td>BigModel 开放平台</td><td>标准按量模型 API</td><td><a href="https://bigmodel.cn/" target="_blank" rel="noreferrer">bigmodel.cn</a>、<a href="https://docs.bigmodel.cn/cn/guide/start/introduction" target="_blank" rel="noreferrer">平台介绍</a></td><td>地图一行；和本套餐不是同一口额度</td></tr><tr><td>ZCode</td><td>可用本套餐的第一方编码工具</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/tool/zcode" target="_blank" rel="noreferrer">tool/zcode</a></td><td>地图一行；本目录不写 Agent 教程</td></tr><tr><td>AutoGLM</td><td>同厂 Agent 产品</td><td><a href="https://www.zhipuai.cn/" target="_blank" rel="noreferrer">zhipuai.cn</a></td><td>地图一行</td></tr><tr><td>AutoClaw</td><td>本地 OpenClaw 客户端</td><td><a href="https://autoglm.zhipuai.cn/autoclaw" target="_blank" rel="noreferrer">autoglm.zhipuai.cn/autoclaw</a></td><td>地图一行</td></tr><tr><td>Zread.ai</td><td>开源仓库阅读产品</td><td><a href="https://zread.ai" target="_blank" rel="noreferrer">zread.ai</a></td><td>地图一行；套餐侧只写 <a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/zread-mcp-server" target="_blank" rel="noreferrer">Zread MCP</a></td></tr><tr><td>AMiner</td><td>学术检索</td><td><a href="https://www.zhipuai.cn/" target="_blank" rel="noreferrer">zhipuai.cn</a></td><td>非本站</td></tr><tr><td>智谱学习中心</td><td>教育</td><td><a href="https://www.zhipuai.cn/" target="_blank" rel="noreferrer">zhipuai.cn</a></td><td>非本站</td></tr><tr><td>智谱AI输入法</td><td>输入法</td><td><a href="https://www.zhipuai.cn/" target="_blank" rel="noreferrer">zhipuai.cn</a></td><td>非本站</td></tr></tbody></table><p>来源：<a href="https://www.zhipuai.cn/" target="_blank" rel="noreferrer">zhipuai.cn</a> 顶栏 / 页脚「产品」、<a href="https://docs.bigmodel.cn/cn/coding-plan/overview" target="_blank" rel="noreferrer">docs.bigmodel.cn 编码套餐</a>。</p><p><strong>容易撞名：</strong></p><ul><li><strong>套餐 ≠ 清言 / Z.ai</strong>。清言是聊天。套餐是给你已经在用的 Claude Code / Cursor 供 GLM。</li><li><strong>套餐 Key ≠ 平台其它 API Key</strong>。团队套餐 Key 不通用（<a href="https://docs.bigmodel.cn/cn/coding-plan/quick-start" target="_blank" rel="noreferrer">快速开始</a>、<a href="https://docs.bigmodel.cn/cn/coding-plan/team" target="_blank" rel="noreferrer">团队版</a>）。</li><li><strong><code>/api/coding/paas/v4</code> ≠ <code>/api/paas/v4</code></strong>。配错端点会报 <code>1113 余额不足</code> 或扣账户余额（<a href="https://docs.bigmodel.cn/cn/coding-plan/faq" target="_blank" rel="noreferrer">FAQ</a>）。</li><li><strong>Coding Tool Helper ≠ 编码 Agent</strong>。<code>npx @z_ai/coding-helper</code> 只负责装工具、灌套餐。</li><li><strong>Helper 支持的 4 个工具 ≠ 适用工具全集</strong>。Helper 当前只有 Claude Code / OpenCode / Crush / Factory Droid（<a href="https://docs.bigmodel.cn/cn/coding-plan/extension/coding-tool-helper" target="_blank" rel="noreferrer">一键安装助手</a>）。Cursor 要按 <a href="https://docs.bigmodel.cn/cn/coding-plan/tool/cursor" target="_blank" rel="noreferrer">Cursor 页</a> 手配。</li></ul><h3 id="快速决策-我该走哪扇门" tabindex="-1">快速决策：我该走哪扇门？ <a class="header-anchor" href="#快速决策-我该走哪扇门" aria-label="Permalink to &quot;快速决策：我该走哪扇门？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在已经在用的 Claude Code / Cursor / Cline 里换 GLM、吃订阅额度</span></span>
<span class="line"><span>│   └── → 本目录（先 Tutorial，再按工具页配置）</span></span>
<span class="line"><span>├── 聊天、写作、通用助手</span></span>
<span class="line"><span>│   └── → 智谱清言 / Z.ai（#74），不是本套餐</span></span>
<span class="line"><span>├── 自建应用 / 网站 / 机器人 / SaaS 里调 GLM</span></span>
<span class="line"><span>│   └── → BigModel 标准 API（FAQ 原文：不可享用 Coding 套餐额度）</span></span>
<span class="line"><span>├── 团队统一席位、账单、IP 白名单</span></span>
<span class="line"><span>│   └── → 团队版（标准版 / 高级版）</span></span>
<span class="line"><span>└── 只要一个「智谱自己的 IDE」</span></span>
<span class="line"><span>    └── → ZCode 是指定工具之一，教程看官方 tool/zcode，本目录不展开</span></span></code></pre></div><p>国内与海外是两套域名。本中文手册默认 <strong>国内</strong>（<code>open.bigmodel.cn</code>）。海外端点见 <a href="https://docs.z.ai/devpack/overview" target="_blank" rel="noreferrer">docs.z.ai/devpack</a> 与英文目录。</p><h2 id="套餐边界-先看这个再订阅" tabindex="-1">套餐边界（先看这个再订阅） <a class="header-anchor" href="#套餐边界-先看这个再订阅" aria-label="Permalink to &quot;套餐边界（先看这个再订阅）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>官方口径</th></tr></thead><tbody><tr><td>可用模型</td><td>所有套餐：<strong>GLM-5.3</strong>、GLM-5-Turbo、GLM-4.7。调用 GLM-5.2 / GLM-5.1 自动切到 GLM-5.3</td></tr><tr><td>能用在哪</td><td>仅限 <a href="https://docs.bigmodel.cn/cn/coding-plan/tool/others#%E4%B8%80%E3%80%81%E9%80%82%E7%94%A8%E5%B7%A5%E5%85%B7" target="_blank" rel="noreferrer">指定工具</a></td></tr><tr><td>额度耗尽</td><td>等下一个 5 小时周期；<strong>不</strong>继续扣资源包 / 账户余额</td></tr><tr><td>国内 Anthropic 端点</td><td><code>https://open.bigmodel.cn/api/anthropic</code></td></tr><tr><td>国内 OpenAI Compatible 端点</td><td><code>https://open.bigmodel.cn/api/coding/paas/v4</code></td></tr><tr><td>个人积分</td><td>Lite 2,000 / 10,000；Pro 12,000 / 60,000；Max 28,000 / 140,000（5 小时 / 每周）</td></tr><tr><td>高峰</td><td>周一至周五 14:00–18:00（UTC+8）；非高峰模型调用按基础积分 <strong>50%</strong> 抵扣</td></tr><tr><td>OpenClaw 等通用 Agent</td><td><strong>次级调度</strong> + 尽力交付；Coding Agent 任务优先</td></tr></tbody></table><p>刊例价以 <a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">订阅页</a> 当时展示为准。文档站 overview 不写人民币价，本页不回填。</p><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 分清门</td><td>本页家族表</td><td>不要进清言，也不要把套餐当标准 API</td></tr><tr><td>2. 订上并接到工具</td><td><a href="./glm-coding.html">Tutorial</a></td><td>15 分钟内用 Helper 或手配跑通 Claude Code / Cursor</td></tr><tr><td>3. 切模型、MCP、排错</td><td><a href="./glm-coding-cookbook.html">Cookbook</a></td><td>GLM-5.3、视觉 / 搜索 MCP、<code>1113</code></td></tr><tr><td>4. 回查数字</td><td><a href="./glm-coding-cheatsheet.html">速查表</a></td><td>端点、积分、命令、指定工具名单</td></tr><tr><td>5. 理清概念</td><td><a href="./glm-coding-glossary.html">术语表</a></td><td>套餐 vs API vs 聊天、积分、次级调度</td></tr></tbody></table><h2 id="功能速查" tabindex="-1">功能速查 <a class="header-anchor" href="#功能速查" aria-label="Permalink to &quot;功能速查&quot;">​</a></h2><p>只列官方编码套餐文档里有独立页的能力。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方文档</th></tr></thead><tbody><tr><td>套餐概览</td><td>模型、积分、指定工具</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/overview" target="_blank" rel="noreferrer">overview</a></td></tr><tr><td>快速开始</td><td>注册、订阅、取 Key、选工具</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/quick-start" target="_blank" rel="noreferrer">quick-start</a></td></tr><tr><td>一键安装助手</td><td><code>npx @z_ai/coding-helper</code></td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/extension/coding-tool-helper" target="_blank" rel="noreferrer">coding-tool-helper</a></td></tr><tr><td>指定工具</td><td>适用 Coding Agent / 通用 Agent 名单</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/tool/others" target="_blank" rel="noreferrer">tool/others</a></td></tr><tr><td>切换模型</td><td>Claude Code <code>settings.json</code> / 其它自定义模型</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/latest-model" target="_blank" rel="noreferrer">latest-model</a></td></tr><tr><td>团队版</td><td>席位、团队 Key、超额按量</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/team" target="_blank" rel="noreferrer">team</a></td></tr><tr><td>视觉 MCP</td><td>本地 <code>@z_ai/mcp-server</code>，模型 GLM-4.6V</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/vision-mcp-server" target="_blank" rel="noreferrer">vision</a></td></tr><tr><td>联网搜索 MCP</td><td>Remote <code>web_search_prime</code></td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/search-mcp-server" target="_blank" rel="noreferrer">search</a></td></tr><tr><td>网页读取 MCP</td><td>Remote Reader</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/reader-mcp-server" target="_blank" rel="noreferrer">reader</a></td></tr><tr><td>开源仓库 MCP</td><td>Remote Zread</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/mcp/zread-mcp-server" target="_blank" rel="noreferrer">zread</a></td></tr><tr><td>GLM in Excel (Beta)</td><td>套餐权益，不是编程 Agent</td><td><a href="https://docs.bigmodel.cn/cn/coding-plan/extension/glm-in-excel" target="_blank" rel="noreferrer">glm-in-excel</a></td></tr></tbody></table>`,20)])])}const u=e(d,[["render",o]]);export{f as __pageData,u as default};
